TEE_Result verify_asymmetric_signature(unsigned long state,
                                       const struct utee_attribute *usr_params,
                                       size_t num_params,
                                       const void *data,
                                       size_t data_len,
                                       const void *sig,
                                       size_t sig_len) {
    TEE_Result result = TEE_ERROR_GENERIC;
    struct session *session = get_current_session();
    struct utee_attribute *attrs = NULL;

    if (!session || !usr_params || !data || !sig) {
        return TEE_ERROR_BAD_PARAMETERS;
    }

    if (!session_check_access(session, TEE_DATA_ACCESS_READ, data, data_len) ||
        !session_check_access(session, TEE_DATA_ACCESS_READ, sig, sig_len)) {
        return TEE_ERROR_ACCESS_DENIED;
    }

    attrs = calloc(num_params, sizeof(*attrs));
    if (!attrs) {
        return TEE_ERROR_OUT_OF_MEMORY;
    }

    memcpy(attrs, usr_params, num_params * sizeof(*usr_params));

    const struct key *key = get_key_from_state(state);
    if (!key || !key->is_initialized) {
        result = TEE_ERROR_BAD_STATE;
        goto cleanup;
    }

    switch (key->algorithm) {
        case TEE_ALG_RSA_VERIFY:
            result = verify_rsa_signature(attrs, num_params, data, data_len, sig, sig_len);
            break;
        case TEE_ALG_DSA_VERIFY:
            result = verify_dsa_signature(attrs, num_params, data, data_len, sig, sig_len);
            break;
        case TEE_ALG_ECDSA_VERIFY:
            result = verify_ecdsa_signature(attrs, num_params, data, data_len, sig, sig_len);
            break;
        default:
            result = TEE_ERROR_NOT_SUPPORTED;
            break;
    }

cleanup:
    free(attrs);
    return result;
}

