TEE_Result verify_asymmetric_signature(
    unsigned long state,
    const struct utee_attribute *usr_params,
    size_t num_params,
    const void *data,
    size_t data_len,
    const void *sig,
    size_t sig_len)
{
    TEE_Result res = TEE_ERROR_GENERIC;
    struct session *session = NULL;
    struct key *key = NULL;
    struct utee_attribute *attrs = NULL;
    size_t i;

    session = get_current_session();
    if (!session) {
        res = TEE_ERROR_BAD_STATE;
        goto exit;
    }

    if (check_access_rights(session, data, data_len) != TEE_SUCCESS) {
        res = TEE_ERROR_ACCESS_DENIED;
        goto exit;
    }

    if (check_access_rights(session, sig, sig_len) != TEE_SUCCESS) {
        res = TEE_ERROR_ACCESS_DENIED;
        goto exit;
    }

    attrs = calloc(num_params, sizeof(*attrs));
    if (!attrs) {
        res = TEE_ERROR_OUT_OF_MEMORY;
        goto exit;
    }

    memcpy(attrs, usr_params, num_params * sizeof(*attrs));

    key = get_key_from_state(state);
    if (!key || !key->is_initialized) {
        res = TEE_ERROR_BAD_PARAMETERS;
        goto free_attrs;
    }

    if (key->algorithm == TEE_ALG_RSASSA_PKCS1_V1_5 ||
        key->algorithm == TEE_ALG_RSASSA_PSS) {
        res = verify_rsa_signature(key, data, data_len, sig, sig_len, attrs, num_params);
    } else if (key->algorithm == TEE_ALG_DSA) {
        res = verify_dsa_signature(key, data, data_len, sig, sig_len, attrs, num_params);
    } else if (key->algorithm == TEE_ALG_ECDSA) {
        res = verify_ecdsa_signature(key, data, data_len, sig, sig_len, attrs, num_params);
    } else {
        res = TEE_ERROR_NOT_SUPPORTED;
    }

free_attrs:
    free(attrs);
exit:
    return res;
}

TEE_Result verify_asymmetric_signature(unsigned long state,
                                       const struct utee_attribute *usr_params,
                                       size_t num_params,
                                       const void *data,
                                       size_t data_len,
                                       const void *sig,
                                       size_t sig_len) {
    TEE_Result res = TEE_SUCCESS;
    struct session *sess = get_current_session();
    struct utee_attribute *attrs = NULL;

    if (!sess || !data || !sig) {
        return TEE_ERROR_BAD_PARAMETERS;
    }

    if (!check_access_rights(sess, data, data_len) ||
        !check_access_rights(sess, sig, sig_len)) {
        return TEE_ERROR_ACCESS_DENIED;
    }

    attrs = calloc(num_params, sizeof(*attrs));
    if (!attrs)
        return TEE_ERROR_OUT_OF_MEMORY;

    memcpy(attrs, usr_params, num_params * sizeof(*attrs));

    res = verify_key_initialization(attrs);
    if (res != TEE_SUCCESS)
        goto out;

    if (attrs->algorithm == TEE_ALG_RSA_PKCS1_V1_5 ||
        attrs->algorithm == TEE_ALG_RSA_PSS) {
        res = verify_rsa_signature(state, attrs, data, data_len, sig, sig_len);
    } else if (attrs->algorithm == TEE_ALG_DSA) {
        res = verify_dsa_signature(state, attrs, data, data_len, sig, sig_len);
    } else if (attrs->algorithm == TEE_ALG_ECDSA) {
        res = verify_ecdsa_signature(state, attrs, data, data_len, sig, sig_len);
    } else {
        res = TEE_ERROR_NOT_SUPPORTED;
    }

out:
    free(attrs);
    return res;
}

TEE_Result verify_asymmetric_signature(unsigned long state,
                                       const struct utee_attribute *usr_params,
                                       size_t num_params,
                                       const void *data,
                                       size_t data_len,
                                       const void *sig,
                                       size_t sig_len)
{
    TEE_Result result = TEE_ERROR_GENERIC;
    struct session *sess = get_current_session();
    struct attribute *attrs = NULL;

    if (!sess || !data || !sig || !usr_params || num_params == 0) {
        return TEE_ERROR_BAD_PARAMETERS;
    }

    if (!check_access_rights(sess, data, data_len) ||
        !check_access_rights(sess, sig, sig_len)) {
        return TEE_ERROR_ACCESS_DENIED;
    }

    attrs = calloc(num_params, sizeof(struct attribute));
    if (!attrs) {
        return TEE_ERROR_OUT_OF_MEMORY;
    }

    for (size_t i = 0; i < num_params; i++) {
        attrs[i] = usr_params[i];
    }

    if (!is_key_initialized(attrs)) {
        result = TEE_ERROR_BAD_STATE;
        goto cleanup;
    }

    switch (get_algorithm(attrs)) {
        case ALGORITHM_RSA:
            result = verify_rsa_signature(attrs, data, data_len, sig, sig_len);
            break;
        case ALGORITHM_DSA:
            result = verify_dsa_signature(attrs, data, data_len, sig, sig_len);
            break;
        case ALGORITHM_ECDSA:
            result = verify_ecdsa_signature(attrs, data, data_len, sig, sig_len);
            break;
        default:
            result = TEE_ERROR_NOT_SUPPORTED;
            break;
    }

cleanup:
    if (attrs) {
        free(attrs);
    }
    return result;
}
